<?php
namespace LaraSelector;
final class LaraSelectorToken {public function __construct(private array $config,private string $key){}public function isInspectable(string$p):bool{return $this->allowed(realpath($p)?:'');}public function make(string$p,int$l):string{$r=realpath($p);$root=realpath($this->config['application_root']);$b=rtrim(strtr(base64_encode(json_encode(['p'=>ltrim(substr($r,strlen($root)),DIRECTORY_SEPARATOR),'l'=>$l,'e'=>time()+$this->config['token_ttl_seconds']])), '+/','-_'),'=');return $b.'.'.hash_hmac('sha256',$b,$this->key);}public function resolve(string$t):array{[$b,$s]=array_pad(explode('.',$t,2),2,null);if(!$b||!$s||!hash_equals(hash_hmac('sha256',$b,$this->key),$s))throw new \InvalidArgumentException('Invalid source identifier.');$d=json_decode(base64_decode(strtr($b,'-_','+/'),true),true);if(!is_array($d)||!isset($d['p'],$d['l'],$d['e'])||$d['e']<time()||!is_int($d['l'])||$d['l']<1)throw new \InvalidArgumentException('Invalid or expired source identifier.');$p=realpath(rtrim($this->config['application_root'],'/').'/'.ltrim($d['p'],'/'));if(!$p||!$this->allowed($p)||!str_ends_with($p,'.blade.php'))throw new \InvalidArgumentException('Source is not allowed.');return['path'=>$p,'relative'=>ltrim(substr($p,strlen(realpath($this->config['application_root']))),'/'),'line'=>$d['l']];}private function allowed(string$p):bool{if(!$p)return false;foreach($this->config['exclude_paths']as$e)if(($r=realpath($e))&&str_starts_with($p,$r.'/'))return false;foreach($this->config['inspect_paths']as$i)if(($r=realpath($i))&&str_starts_with($p,$r.'/'))return true;return false;}}
